const { World, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

class TodoWorld extends World {
  constructor(options) {
    super(options);
    this.dom = null;
    this.document = null;
    this.window = null;
    this.appHtml = '';
  }

  loadApp(html) {
    this.appHtml = html;
    this.window = new Window({ url: 'http://localhost' });
    this.window.document.write(html);
    this.window.document.close();
    this.document = this.window.document;
  }

  getTodoItems() {
    return Array.from(this.document.querySelectorAll('.todo-list li'));
  }

  getTodoTexts() {
    return this.getTodoItems().map(li => {
      const label = li.querySelector('label');
      return label ? label.textContent.trim() : '';
    });
  }

  getActiveCount() {
    return this.getTodoItems().filter(li => !li.classList.contains('completed')).length;
  }

  getCompletedCount() {
    return this.getTodoItems().filter(li => li.classList.contains('completed')).length;
  }

  isTodoCompleted(text) {
    const items = this.getTodoItems();
    const li = items.find(item => {
      const label = item.querySelector('label');
      return label && label.textContent.trim() === text;
    });
    return li ? li.classList.contains('completed') : false;
  }

  findTodoByLabel(text) {
    const items = this.getTodoItems();
    return items.find(item => {
      const label = item.querySelector('label');
      return label && label.textContent.trim() === text;
    });
  }
}

setWorldConstructor(TodoWorld);

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');
const fs = require('fs');
const path = require('path');

function loadAppHtml(world) {
  const templatePath = path.resolve(__dirname, '../../assets/app-template.index.html');
  const html = fs.readFileSync(templatePath, 'utf-8');
  world.loadApp(html);
  // Load the app script if it exists
  const appScriptPath = path.resolve(__dirname, '../../js/app.js');
  if (fs.existsSync(appScriptPath)) {
    const appScript = fs.readFileSync(appScriptPath, 'utf-8');
    const scriptEl = world.document.createElement('script');
    scriptEl.textContent = appScript;
    world.document.body.appendChild(scriptEl);
  }
}

function createTodoLi(world, title, completed) {
  const li = world.document.createElement('li');
  if (completed) li.classList.add('completed');
  li.innerHTML = `
    <div class="view">
      <input class="toggle" type="checkbox" ${completed ? 'checked' : ''}>
      <label>${title}</label>
      <button class="destroy"></button>
    </div>
    <input class="edit" value="${title}">
  `;
  return li;
}

function seedTodoState(world, todos) {
  const todoList = world.document.querySelector('.todo-list');
  todoList.innerHTML = '';
  for (const todo of todos) {
    todoList.appendChild(createTodoLi(world, todo.title, todo.completed));
  }
  // Show main and footer
  const main = world.document.querySelector('.main');
  const footer = world.document.querySelector('.footer');
  if (main) main.style.display = '';
  if (footer) footer.style.display = '';
  // Update toggle-all checkbox
  const toggleAll = world.document.querySelector('#toggle-all');
  if (toggleAll) {
    toggleAll.checked = todos.length > 0 && todos.every(t => t.completed);
  }
  // Update counter
  updateCounter(world, todos);
  // Update clear-completed visibility
  updateClearCompleted(world, todos);
}

function updateCounter(world, todos) {
  const count = todos.filter(t => !t.completed).length;
  const counter = world.document.querySelector('.todo-count');
  if (counter) {
    const pluralized = count === 1 ? 'item' : 'items';
    counter.innerHTML = `<strong>${count}</strong> ${pluralized} left`;
  }
}

function updateClearCompleted(world, todos) {
  const hasCompleted = todos.some(t => t.completed);
  const btn = world.document.querySelector('.clear-completed');
  if (btn) {
    btn.style.display = hasCompleted ? '' : 'none';
  }
}

function getTodosFromDOM(world) {
  return world.getTodoItems().map(li => ({
    title: li.querySelector('label').textContent.trim(),
    completed: li.classList.contains('completed')
  }));
}

function saveTodosToLocalStorage(world, todos) {
  world.window.localStorage.setItem('todos-shakedown', JSON.stringify(todos));
}

function loadTodosFromLocalStorage(world) {
  const data = world.window.localStorage.getItem('todos-shakedown');
  return data ? JSON.parse(data) : [];
}

// ==================== GIVEN ====================

Given('the todo app is loaded with no todos', function () {
  loadAppHtml(this);
  seedTodoState(this, []);
});

Given('the todo app is loaded with a todo {string}', function (title) {
  loadAppHtml(this);
  seedTodoState(this, [{ title, completed: false }]);
});

Given('the todo app is loaded with a completed todo {string}', function (title) {
  loadAppHtml(this);
  seedTodoState(this, [{ title, completed: true }]);
});

Given('the todo app is loaded with todos {string} and {string}', function (title1, title2) {
  loadAppHtml(this);
  seedTodoState(this, [
    { title: title1, completed: false },
    { title: title2, completed: false }
  ]);
});

Given('the todo app is loaded with a completed todo {string} and an active todo {string}', function (compTitle, actTitle) {
  loadAppHtml(this);
  seedTodoState(this, [
    { title: compTitle, completed: true },
    { title: actTitle, completed: false }
  ]);
});

Given('the todo app is loaded with an active todo {string}', function (title) {
  loadAppHtml(this);
  seedTodoState(this, [{ title, completed: false }]);
});

Given('the todo app is loaded with completed todos {string} and {string}', function (title1, title2) {
  loadAppHtml(this);
  seedTodoState(this, [
    { title: title1, completed: true },
    { title: title2, completed: true }
  ]);
});

// ==================== WHEN ====================

When('the user enters {string} as a new todo', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13 }));
});

When('the user toggles the todo {string}', function (title) {
  const li = this.findTodoByLabel(title);
  const checkbox = li.querySelector('.toggle');
  checkbox.click();
});

When('the user toggles the mark-all checkbox on', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  toggleAll.checked = true;
  toggleAll.dispatchEvent(new this.window.Event('change'));
});

When('the user toggles the mark-all checkbox off', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  toggleAll.checked = false;
  toggleAll.dispatchEvent(new this.window.Event('change'));
});

When('the user double-clicks the todo {string}', function (title) {
  const li = this.findTodoByLabel(title);
  const label = li.querySelector('label');
  label.dispatchEvent(new this.window.Event('dblclick'));
});

When('the user types {string} and presses Enter', function (text) {
  const editingInput = this.document.querySelector('.todo-list li.editing .edit');
  editingInput.value = text;
  editingInput.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13 }));
});

When('the user types {string} and presses Escape', function (text) {
  const editingInput = this.document.querySelector('.todo-list li.editing .edit');
  editingInput.value = text;
  editingInput.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Escape', keyCode: 27 }));
});

When('the user types {string} and blurs', function (text) {
  const editingInput = this.document.querySelector('.todo-list li.editing .edit');
  editingInput.value = text;
  editingInput.dispatchEvent(new this.window.Event('blur'));
});

When('the user clears the edit field and presses Enter', function () {
  const editingInput = this.document.querySelector('.todo-list li.editing .edit');
  editingInput.value = '';
  editingInput.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13 }));
});

When('the user destroys the todo {string}', function (title) {
  const li = this.findTodoByLabel(title);
  const destroyBtn = li.querySelector('.destroy');
  destroyBtn.click();
});

When('the user clicks Clear completed', function () {
  const btn = this.document.querySelector('.clear-completed');
  btn.click();
});

When('the user navigates to the All filter', function () {
  const allLink = this.document.querySelector('.filters a[href="#/"]');
  allLink.click();
});

When('the user navigates to the Active filter', function () {
  const activeLink = this.document.querySelector('.filters a[href="#/active"]');
  activeLink.click();
});

When('the user navigates to the Completed filter', function () {
  const completedLink = this.document.querySelector('.filters a[href="#/completed"]');
  completedLink.click();
});

When('the page is reloaded', function () {
  const todos = getTodosFromDOM(this);
  saveTodosToLocalStorage(this, todos);
  loadAppHtml(this);
  // Re-apply localStorage
  const saved = loadTodosFromLocalStorage(this);
  if (saved.length > 0) {
    seedTodoState(this, saved);
  }
});

// ==================== THEN ====================

Then('a todo {string} appears in the list', function (title) {
  const texts = this.getTodoTexts();
  assert.ok(texts.includes(title), `Expected todo "${title}" in list, got: ${JSON.stringify(texts)}`);
});

Then('the new todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '');
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  assert.ok(main, 'Main section exists');
  assert.notStrictEqual(main.style.display, 'none', 'Main section should be visible');
});

Then('the footer is visible', function () {
  const footer = this.document.querySelector('.footer');
  assert.ok(footer, 'Footer exists');
  assert.notStrictEqual(footer.style.display, 'none', 'Footer should be visible');
});

Then('no todos appear in the list', function () {
  const items = this.getTodoItems();
  assert.strictEqual(items.length, 0, `Expected no todos, got ${items.length}`);
});

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  assert.ok(main, 'Main section exists');
  assert.strictEqual(main.style.display, 'none', 'Main section should be hidden');
});

Then('the footer is hidden', function () {
  const footer = this.document.querySelector('.footer');
  assert.ok(footer, 'Footer exists');
  assert.strictEqual(footer.style.display, 'none', 'Footer should be hidden');
});

Then('the todo {string} is completed', function (title) {
  assert.ok(this.isTodoCompleted(title), `Todo "${title}" should be completed`);
});

Then('the todo {string} is active', function (title) {
  assert.ok(!this.isTodoCompleted(title), `Todo "${title}" should be active`);
});

Then('all todos are completed', function () {
  const items = this.getTodoItems();
  assert.ok(items.length > 0, 'Expected at least one todo');
  items.forEach(li => {
    assert.ok(li.classList.contains('completed'), `Expected all todos to be completed`);
  });
});

Then('the mark-all checkbox is unchecked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  assert.strictEqual(toggleAll.checked, false, 'Mark-all should be unchecked');
});

Then('all todos are active', function () {
  const items = this.getTodoItems();
  assert.ok(items.length > 0, 'Expected at least one todo');
  items.forEach(li => {
    assert.ok(!li.classList.contains('completed'), `Expected all todos to be active`);
  });
});

Then('the todo {string} is in editing mode', function (title) {
  const li = this.findTodoByLabel(title);
  assert.ok(li.classList.contains('editing'), `Todo "${title}" should be in editing mode`);
});

Then('the todo {string} is not in editing mode', function (title) {
  const li = this.findTodoByLabel(title);
  assert.ok(!li.classList.contains('editing'), `Todo "${title}" should not be in editing mode`);
});

Then('the todo list contains {int} items', function (count) {
  const items = this.getTodoItems();
  assert.strictEqual(items.length, count, `Expected ${count} items, got ${items.length}`);
});

Then('the counter shows {string}', function (expected) {
  const counter = this.document.querySelector('.todo-count');
  assert.strictEqual(counter.textContent.trim(), expected, `Expected counter "${expected}", got "${counter.textContent.trim()}"`);
});

Then('the Clear completed button is hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.ok(btn, 'Clear completed button exists');
  assert.strictEqual(btn.style.display, 'none', 'Clear completed button should be hidden');
});

Then('the Clear completed button is visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.ok(btn, 'Clear completed button exists');
  assert.notStrictEqual(btn.style.display, 'none', 'Clear completed button should be visible');
});

Then('no completed todo {string} appears in the list', function (title) {
  const items = this.getTodoItems();
  const completedItems = items.filter(li => li.classList.contains('completed'));
  const titles = completedItems.map(li => li.querySelector('label').textContent.trim());
  assert.ok(!titles.includes(title), `Completed todo "${title}" should not appear`);
});

Then('no active todo {string} appears in the list', function (title) {
  const items = this.getTodoItems();
  const activeItems = items.filter(li => !li.classList.contains('completed'));
  const titles = activeItems.map(li => li.querySelector('label').textContent.trim());
  assert.ok(!titles.includes(title), `Active todo "${title}" should not appear`);
});

Then('the All filter is selected', function () {
  const allLink = this.document.querySelector('.filters a[href="#/"]');
  assert.ok(allLink.classList.contains('selected'), 'All filter should be selected');
});

Then('the Active filter is selected', function () {
  const activeLink = this.document.querySelector('.filters a[href="#/active"]');
  assert.ok(activeLink.classList.contains('selected'), 'Active filter should be selected');
});

Then('the Completed filter is selected', function () {
  const completedLink = this.document.querySelector('.filters a[href="#/completed"]');
  assert.ok(completedLink.classList.contains('selected'), 'Completed filter should be selected');
});

Then('localStorage contains a todo {string}', function (title) {
  const todos = loadTodosFromLocalStorage(this);
  const titles = todos.map(t => t.title);
  assert.ok(titles.includes(title), `localStorage should contain todo "${title}"`);
});

Then('localStorage contains a completed todo {string}', function (title) {
  const todos = loadTodosFromLocalStorage(this);
  const todo = todos.find(t => t.title === title);
  assert.ok(todo, `localStorage should contain todo "${title}"`);
  assert.ok(todo.completed, `Todo "${title}" should be completed in localStorage`);
});

