arguments.content:
(function () {
  'use strict';

  var STORAGE_KEY = 'todos-shakedown';

  var todoList = document.querySelector('.todo-list');
  var newTodoInput = document.querySelector('.new-todo');
  var toggleAllCheckbox = document.querySelector('#toggle-all');
  var clearCompletedBtn = document.querySelector('.clear-completed');
  var mainSection = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var counter = document.querySelector('.todo-count');
  var filterLinks = document.querySelectorAll('.filters a');

  function getTodos() {
    var data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  }

  function saveTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
  }

  function createTodoLi(title, completed) {
    var li = document.createElement('li');
    if (completed) li.classList.add('completed');
    li.setAttribute('data-id', generateId());

    var div = document.createElement('div');
    div.className = 'view';

    var checkbox = document.createElement('input');
    checkbox.className = 'toggle';
    checkbox.type = 'checkbox';
    if (completed) checkbox.checked = true;

    var label = document.createElement('label');
    label.textContent = title;

    var destroyBtn = document.createElement('button');
    destroyBtn.className = 'destroy';

    div.appendChild(checkbox);
    div.appendChild(label);
    div.appendChild(destroyBtn);

    var editInput = document.createElement('input');
    editInput.className = 'edit';
    editInput.value = title;

    li.appendChild(div);
    li.appendChild(editInput);
    return li;
  }

  function render() {
    var todos = getTodos();
    var currentFilter = getFilter();

    todoList.innerHTML = '';

    todos.forEach(function (todo) {
      var li = createTodoLi(todo.title, todo.completed);
      li.setAttribute('data-id', todo.id);
      todoList.appendChild(li);
    });

    updateVisibility(todos);
    updateCounter(todos);
    updateToggleAll(todos);
    updateClearCompleted(todos);
    applyFilter(currentFilter);
    updateFilterLinks(currentFilter);
  }

  function updateVisibility(todos) {
    if (todos.length === 0) {
      mainSection.style.display = 'none';
      footer.style.display = 'none';
    } else {
      mainSection.style.display = '';
      footer.style.display = '';
    }
  }

  function updateCounter(todos) {
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var pluralized = activeCount === 1 ? 'item' : 'items';
    counter.innerHTML = '<strong>' + activeCount + '</strong> ' + pluralized + ' left';
  }

  function updateToggleAll(todos) {
    if (todos.length === 0) {
      toggleAllCheckbox.checked = false;
    } else {
      toggleAllCheckbox.checked = todos.every(function (t) { return t.completed; });
    }
  }

  function updateClearCompleted(todos) {
    var hasCompleted = todos.some(function (t) { return t.completed; });
    clearCompletedBtn.style.display = hasCompleted ? '' : 'none';
  }

  function getFilter() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function applyFilter(filter) {
    var items = todoList.querySelectorAll('li');
    items.forEach(function (li) {
      var isCompleted = li.classList.contains('completed');
      var show = false;
      if (filter === 'all') show = true;
      else if (filter === 'active') show = !isCompleted;
      else if (filter === 'completed') show = isCompleted;
      li.style.display = show ? '' : 'none';
    });
  }

  function updateFilterLinks(filter) {
    filterLinks.forEach(function (link) {
      link.classList.remove('selected');
      if (filter === 'all' && link.getAttribute('href') === '#/') {
        link.classList.add('selected');
      } else if (filter === 'active' && link.getAttribute('href') === '#/active') {
        link.classList.add('selected');
      } else if (filter === 'completed' && link.getAttribute('href') === '#/completed') {
        link.classList.add('selected');
      }
    });
  }

  function findTodoById(id) {
    var todos = getTodos();
    return todos.find(function (t) { return t.id === id; });
  }

  function updateTodo(id, changes) {
    var todos = getTodos();
    var idx = todos.findIndex(function (t) { return t.id === id; });
    if (idx !== -1) {
      Object.assign(todos[idx], changes);
      saveTodos(todos);
    }
    return todos;
  }

  function removeTodo(id) {
    var todos = getTodos().filter(function (t) { return t.id !== id; });
    saveTodos(todos);
    return todos;
  }

  // --- Event handlers ---

  // New todo input
  newTodoInput.addEventListener('keyup', function (e) {
    if (e.key === 'Enter' || e.keyCode === 13) {
      var text = newTodoInput.value.trim();
      if (text === '') return;
      var todos = getTodos();
      var newTodo = { id: generateId(), title: text, completed: false };
      todos.push(newTodo);
      saveTodos(todos);
      newTodoInput.value = '';
      render();
    }
  });

  // Toggle individual todo
  todoList.addEventListener('change', function (e) {
    if (e.target.classList.contains('toggle')) {
      var li = e.target.closest('li');
      var id = li.getAttribute('data-id');
      var isCompleted = e.target.checked;
      li.classList.toggle('completed', isCompleted);
      var todos = updateTodo(id, { completed: isCompleted });
      updateCounter(todos);
      updateToggleAll(todos);
      updateClearCompleted(todos);
      applyFilter(getFilter());
    }
  });

  // Destroy todo
  todoList.addEventListener('click', function (e) {
    if (e.target.classList.contains('destroy')) {
      var li = e.target.closest('li');
      var id = li.getAttribute('data-id');
      var todos = removeTodo(id);
      render();
    }
  });

  // Double-click to edit
  todoList.addEventListener('dblclick', function (e) {
    if (e.target.tagName === 'LABEL') {
      var li = e.target.closest('li');
      li.classList.add('editing');
      var editInput = li.querySelector('.edit');
      editInput.focus();
    }
  });

  // Edit: Enter to save, Escape to cancel
  todoList.addEventListener('keyup', function (e) {
    var editInput = e.target;
    if (!editInput.classList.contains('edit')) return;
    var li = editInput.closest('li');
    var id = li.getAttribute('data-id');

    if (e.key === 'Enter' || e.keyCode === 13) {
      var text = editInput.value.trim();
      if (text === '') {
        removeTodo(id);
        render();
        return;
      }
      updateTodo(id, { title: text });
      li.classList.remove('editing');
      render();
    } else if (e.key === 'Escape' || e.keyCode === 27) {
      var todo = findTodoById(id);
      if (todo) editInput.value = todo.title;
      li.classList.remove('editing');
    }
  });

  // Edit: blur to save
  todoList.addEventListener('focusout', function (e) {
    if (!e.target.classList.contains('edit')) return;
    var editInput = e.target;
    var li = editInput.closest('li');
    if (!li) return;
    var id = li.getAttribute('data-id');

    setTimeout(function () {
      var text = editInput.value.trim();
      if (text === '') {
        removeTodo(id);
        render();
        return;
      }
      updateTodo(id, { title: text });
      li.classList.remove('editing');
      render();
    }, 0);
  });

  // Toggle all
  toggleAllCheckbox.addEventListener('change', function () {
    var checked = toggleAllCheckbox.checked;
    var todos = getTodos().map(function (t) {
      t.completed = checked;
      return t;
    });
    saveTodos(todos);
    render();
  });

  // Clear completed
  clearCompletedBtn.addEventListener('click', function () {
    var todos = getTodos().filter(function (t) { return !t.completed; });
    saveTodos(todos);
    render();
  });

  // Routing
  window.addEventListener('hashchange', function () {
    render();
  });

  // Initialize
  render();
})();

