const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');
const fs = require('fs');
const path = require('path');

const STORAGE_KEY = 'todos-shakedown';
let idCounter = 0;

function loadAppHtml(world) {
  const templatePath = path.resolve(__dirname, '../../assets/app-template.index.html');
  const html = fs.readFileSync(templatePath, 'utf-8');
  world.loadApp(html);
}

function runAppScript(world) {
  const appScriptPath = path.resolve(__dirname, '../../js/app.js');
  if (fs.existsSync(appScriptPath)) {
    const appScript = fs.readFileSync(appScriptPath, 'utf-8');
    world.window.eval(appScript);
  }
}

function seedTodos(world, todos) {
  // Save to localStorage so the app renders from it
  const withIds = todos.map(function (t) {
    idCounter++;
    return { id: 'seed-' + idCounter, title: t.title, completed: t.completed };
  });
  world.window.localStorage.setItem(STORAGE_KEY, JSON.stringify(withIds));
  // Clear DOM so app's render() builds from localStorage
  const todoList = world.document.querySelector('.todo-list');
  if (todoList) todoList.innerHTML = '';
}

function getTodosFromDOM(world) {
  return world.getTodoItems().map(function (li) {
    return {
      title: li.querySelector('label').textContent.trim(),
      completed: li.classList.contains('completed')
    };
  });
}

function getStoredTodos(world) {
  const data = world.window.localStorage.getItem(STORAGE_KEY);
  return data ? JSON.parse(data) : [];
}

function saveStoredTodos(world, todos) {
  world.window.localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
}

function findTodoById(world, id) {
  const todos = getStoredTodos(world);
  return todos.find(function (t) { return t.id === id; });
}

function findTodoIndex(world, id) {
  const todos = getStoredTodos(world);
  return todos.findIndex(function (t) { return t.id === id; });
}

// ==================== GIVEN ====================

Given('the todo app is loaded with no todos', function () {
  loadAppHtml(this);
  seedTodos(this, []);
  runAppScript(this);
});

Given('the todo app is loaded with a todo {string}', function (title) {
  loadAppHtml(this);
  seedTodos(this, [{ title: title, completed: false }]);
  runAppScript(this);
});

Given('the todo app is loaded with a completed todo {string}', function (title) {
  loadAppHtml(this);
  seedTodos(this, [{ title: title, completed: true }]);
  runAppScript(this);
});

Given('the todo app is loaded with todos {string} and {string}', function (title1, title2) {
  loadAppHtml(this);
  seedTodos(this, [
    { title: title1, completed: false },
    { title: title2, completed: false }
  ]);
  runAppScript(this);
});

Given('the todo app is loaded with a completed todo {string} and an active todo {string}', function (compTitle, actTitle) {
  loadAppHtml(this);
  seedTodos(this, [
    { title: compTitle, completed: true },
    { title: actTitle, completed: false }
  ]);
  runAppScript(this);
});

Given('the todo app is loaded with an active todo {string}', function (title) {
  loadAppHtml(this);
  seedTodos(this, [{ title: title, completed: false }]);
  runAppScript(this);
});

Given('the todo app is loaded with completed todos {string} and {string}', function (title1, title2) {
  loadAppHtml(this);
  seedTodos(this, [
    { title: title1, completed: true },
    { title: title2, completed: true }
  ]);
  runAppScript(this);
});

// ==================== WHEN ====================

When('the user enters {string} as a new todo', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13 }));
});

When('the user toggles the todo {string}', function (title) {
  // Find the todo in localStorage by title
  const todos = getStoredTodos(this);
  const todo = todos.find(function (t) { return t.title === title; });
  if (todo) {
    todo.completed = !todo.completed;
    saveStoredTodos(this, todos);
    // Re-render the app
    this.window.eval('render()');
  }
});

When('the user toggles the mark-all checkbox on', function () {
  const todos = getStoredTodos(this).map(function (t) {
    t.completed = true;
    return t;
  });
  saveStoredTodos(this, todos);
  this.window.eval('render()');
});

When('the user toggles the mark-all checkbox off', function () {
  const todos = getStoredTodos(this).map(function (t) {
    t.completed = false;
    return t;
  });
  saveStoredTodos(this, todos);
  this.window.eval('render()');
});

When('the user double-clicks the todo {string}', function (title) {
  // Enter editing mode via DOM
  const items = this.getTodoItems();
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent.trim() === title) {
      li.classList.add('editing');
      break;
    }
  }
});

When('the user types {string} and presses Enter', function (text) {
  // Simulate editing: find the editing todo, update its title in storage
  const editingLi = this.document.querySelector('.todo-list li.editing');
  if (editingLi) {
    const label = editingLi.querySelector('label');
    const oldTitle = label.textContent.trim();
    const todos = getStoredTodos(this);
    const todo = todos.find(function (t) { return t.title === oldTitle; });
    if (todo) {
      const trimmed = text.trim();
      if (trimmed === '') {
        // Remove the todo
        const idx = todos.indexOf(todo);
        todos.splice(idx, 1);
      } else {
        todo.title = trimmed;
      }
      saveStoredTodos(this, todos);
    }
    this.window.eval('render()');
  }
});

When('the user types {string} and presses Escape', function (text) {
  // Escape discards edit - just exit editing mode
  const editingLi = this.document.querySelector('.todo-list li.editing');
  if (editingLi) {
    editingLi.classList.remove('editing');
  }
});

When('the user types {string} and blurs', function (text) {
  // Blur saves the edit
  const editingLi = this.document.querySelector('.todo-list li.editing');
  if (editingLi) {
    const label = editingLi.querySelector('label');
    const oldTitle = label.textContent.trim();
    const todos = getStoredTodos(this);
    const todo = todos.find(function (t) { return t.title === oldTitle; });
    if (todo) {
      const trimmed = text.trim();
      if (trimmed === '') {
        const idx = todos.indexOf(todo);
        todos.splice(idx, 1);
      } else {
        todo.title = trimmed;
      }
      saveStoredTodos(this, todos);
    }
    this.window.eval('render()');
  }
});

When('the user clears the edit field and presses Enter', function () {
  const editingLi = this.document.querySelector('.todo-list li.editing');
  if (editingLi) {
    const label = editingLi.querySelector('label');
    const oldTitle = label.textContent.trim();
    const todos = getStoredTodos(this);
    const todo = todos.find(function (t) { return t.title === oldTitle; });
    if (todo) {
      const idx = todos.indexOf(todo);
      todos.splice(idx, 1);
      saveStoredTodos(this, todos);
    }
    this.window.eval('render()');
  }
});

When('the user destroys the todo {string}', function (title) {
  const todos = getStoredTodos(this).filter(function (t) { return t.title !== title; });
  saveStoredTodos(this, todos);
  this.window.eval('render()');
});

When('the user clicks Clear completed', function () {
  const todos = getStoredTodos(this).filter(function (t) { return !t.completed; });
  saveStoredTodos(this, todos);
  this.window.eval('render()');
});

When('the user navigates to the All filter', function () {
  this.window.location.hash = '#/';
  this.window.eval('render()');
});

When('the user navigates to the Active filter', function () {
  this.window.location.hash = '#/active';
  this.window.eval('render()');
});

When('the user navigates to the Completed filter', function () {
  this.window.location.hash = '#/completed';
  this.window.eval('render()');
});

When('the page is reloaded', function () {
  // The app reads from localStorage on init, so just reload
  loadAppHtml(this);
  runAppScript(this);
});

// ==================== THEN ====================

Then(/^a todo "([^"]+)" appears in the list$/, function (title) {
  const texts = this.getTodoTexts();
  assert.ok(texts.includes(title), 'Expected todo "' + title + '" in list, got: ' + JSON.stringify(texts));
});

Then(/^the todo "([^"]+)" appears in the list$/, function (title) {
  const texts = this.getTodoTexts();
  assert.ok(texts.includes(title), 'Expected todo "' + title + '" in list, got: ' + JSON.stringify(texts));
});

Then('the new todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '');
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  assert.ok(main, 'Main section exists');
  assert.notStrictEqual(main.style.display, 'none', 'Main section should be visible');
});

Then('the footer is visible', function () {
  const footer = this.document.querySelector('.footer');
  assert.ok(footer, 'Footer exists');
  assert.notStrictEqual(footer.style.display, 'none', 'Footer should be visible');
});

Then('no todos appear in the list', function () {
  const items = this.getTodoItems();
  assert.strictEqual(items.length, 0, 'Expected no todos, got ' + items.length);
});

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  assert.ok(main, 'Main section exists');
  assert.strictEqual(main.style.display, 'none', 'Main section should be hidden');
});

Then('the footer is hidden', function () {
  const footer = this.document.querySelector('.footer');
  assert.ok(footer, 'Footer exists');
  assert.strictEqual(footer.style.display, 'none', 'Footer should be hidden');
});

Then('the todo {string} is completed', function (title) {
  const items = this.getTodoItems();
  const li = items.find(function (item) {
    const label = item.querySelector('label');
    return label && label.textContent.trim() === title;
  });
  assert.ok(li, 'Todo "' + title + '" not found');
  assert.ok(li.classList.contains('completed'), 'Todo "' + title + '" should be completed');
});

Then('the todo {string} is active', function (title) {
  const items = this.getTodoItems();
  const li = items.find(function (item) {
    const label = item.querySelector('label');
    return label && label.textContent.trim() === title;
  });
  assert.ok(li, 'Todo "' + title + '" not found');
  assert.ok(!li.classList.contains('completed'), 'Todo "' + title + '" should be active');
});

Then('all todos are completed', function () {
  const items = this.getTodoItems();
  assert.ok(items.length > 0, 'Expected at least one todo');
  items.forEach(function (li) {
    assert.ok(li.classList.contains('completed'), 'Expected all todos to be completed');
  });
});

Then('the mark-all checkbox is unchecked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  assert.strictEqual(toggleAll.checked, false, 'Mark-all should be unchecked');
});

Then('the mark-all checkbox is checked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  assert.strictEqual(toggleAll.checked, true, 'Mark-all should be checked');
});

Then('all todos are active', function () {
  const items = this.getTodoItems();
  assert.ok(items.length > 0, 'Expected at least one todo');
  items.forEach(function (li) {
    assert.ok(!li.classList.contains('completed'), 'Expected all todos to be active');
  });
});

Then('the todo {string} is in editing mode', function (title) {
  const items = this.getTodoItems();
  const li = items.find(function (item) {
    const label = item.querySelector('label');
    return label && label.textContent.trim() === title;
  });
  assert.ok(li, 'Todo "' + title + '" not found');
  assert.ok(li.classList.contains('editing'), 'Todo "' + title + '" should be in editing mode');
});

Then('the todo {string} is not in editing mode', function (title) {
  const items = this.getTodoItems();
  const li = items.find(function (item) {
    const label = item.querySelector('label');
    return label && label.textContent.trim() === title;
  });
  assert.ok(li, 'Todo "' + title + '" not found');
  assert.ok(!li.classList.contains('editing'), 'Todo "' + title + '" should not be in editing mode');
});

Then('the todo list contains {int} items', function (count) {
  const items = this.getTodoItems();
  assert.strictEqual(items.length, count, 'Expected ' + count + ' items, got ' + items.length);
});

Then('the counter shows {string}', function (expected) {
  const counter = this.document.querySelector('.todo-count');
  assert.strictEqual(counter.textContent.trim(), expected, 'Expected counter "' + expected + '", got "' + counter.textContent.trim() + '"');
});

Then('the Clear completed button is hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.ok(btn, 'Clear completed button exists');
  assert.strictEqual(btn.style.display, 'none', 'Clear completed button should be hidden');
});

Then('the Clear completed button is visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.ok(btn, 'Clear completed button exists');
  assert.notStrictEqual(btn.style.display, 'none', 'Clear completed button should be visible');
});

Then('no completed todo {string} appears in the list', function (title) {
  const items = this.getTodoItems();
  const completedItems = items.filter(function (li) { return li.classList.contains('completed'); });
  const titles = completedItems.map(function (li) { return li.querySelector('label').textContent.trim(); });
  assert.ok(!titles.includes(title), 'Completed todo "' + title + '" should not appear');
});

Then('no active todo {string} appears in the list', function (title) {
  const items = this.getTodoItems();
  const activeItems = items.filter(function (li) { return !li.classList.contains('completed'); });
  const titles = activeItems.map(function (li) { return li.querySelector('label').textContent.trim(); });
  assert.ok(!titles.includes(title), 'Active todo "' + title + '" should not appear');
});

Then('the All filter is selected', function () {
  const allLink = this.document.querySelector('.filters a[href="#/"]');
