function loadAppHtml(world) {
  // Preserve localStorage across window recreation
  const prevStorage = {};
  if (world.window && world.window.localStorage) {
    for (let i = 0; i < world.window.localStorage.length; i++) {
      const key = world.window.localStorage.key(i);
